// OTHVM Sleep Monitor - handle a Telegram URL button click, update the session, show an Arabic page.
const q = $json.query || $json;
const action = String(q.action || '').toLowerCase();
const sid = String(q.session_id || '');
const minutes = Number(q.minutes || 10);
const allowed = ['woke', 'still', 'snooze', 'cancel'];
let r = { ok: false, error: 'invalid request' };
if (allowed.indexOf(action) >= 0 && sid) {
  try {
    r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://127.0.0.1:8765/tools/sleep',
      headers: { 'Content-Type': 'application/json', 'X-API-Key': 'REPLACE_WITH_MCP_API_KEY' },
      body: { action: action, session_id: sid, minutes: minutes },
      json: true,
      timeout: 45000
    });
  } catch (e) {
    r = { ok: false, error: String((e && e.message) || e) };
  }
}
const reply = String(r.reply || (r.ok ? 'تم.' : ('خطأ: ' + (r.error || 'تعذر تنفيذ الطلب'))));
const safe = reply.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
const icon = r.ok ? '✅' : '⚠️';
const title = r.ok ? 'تم' : 'حصل خطأ';
const html = '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1">'
  + '<title>OTHVM Sleep</title><style>'
  + 'body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#0b1220;color:#e5e7eb;font-family:system-ui,Segoe UI,Arial,sans-serif}'
  + '.card{max-width:520px;margin:24px;padding:32px 28px;border-radius:24px;background:#111a2e;border:1px solid #24324d;box-shadow:0 20px 60px rgba(0,0,0,.35);text-align:center}'
  + '.icon{font-size:56px;line-height:1;margin-bottom:12px}'
  + 'h1{font-size:26px;margin:0 0 14px}'
  + 'p{font-size:17px;line-height:1.8;margin:0 0 10px;color:#cbd5e1}'
  + '.hint{font-size:13px;color:#7c8aa5;margin-top:22px}'
  + '</style></head><body><div class="card"><div class="icon">' + icon + '</div><h1>' + title + '</h1><p>' + safe + '</p>'
  + '<p class="hint">يمكنك قفل الصفحة والعودة إلى تيليجرام.</p></div></body></html>';
return [{ json: { ok: !!r.ok, reply: reply, html: html, action: action, session_id: sid } }];

// OTHVM Sleep Monitor - every 5 minutes ask the MCP to send due wake checks.
try {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://127.0.0.1:8765/tools/sleep',
    headers: { 'Content-Type': 'application/json', 'X-API-Key': 'REPLACE_WITH_MCP_API_KEY' },
    body: { action: 'due' },
    json: true,
    timeout: 45000
  });
  return [{ json: r }];
} catch (e) {
  return [{ json: { ok: false, error: String((e && e.message) || e) } }];
}
